from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class MplanenwParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_oamPeerIpAddress(execution_config, kwargs['env_config'])
        self.set_parameter('oamTls', 'off')

        enb_id = self.enb_ent_config['id']
        if self.enb_ent_config['is_ipv4']:
            mPlaneIpv4AddressDN = f'MRBTS-{enb_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1'
            self.set_parameter('mPlaneIpv4AddressDN', mPlaneIpv4AddressDN)

        if self.enb_ent_config['is_ipv6_mplane']:
            mPlaneIpv6AddressDN = f'MRBTS-{enb_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV6-1'
            self.set_parameter('mPlaneIpv6AddressDN', mPlaneIpv6AddressDN)

    def set_oamPeerIpAddress(self, execution_config, env_config):
        if 'oam_peer_ip' not in self.enb_ent_config and execution_config['release'] < 21.7:
            oam_ip = env_config['EMSSIM_IP']
            self.set_parameter('oamPeerIpAddress', oam_ip)
